assertions.text:
interface OrderDetailData {
  id: string;
  clientId: string | null;
  /** A conversion designates series for a company already on file. */
  filingPath: "NEW" | "CONVERT";
  existingLlcName: string;
  sunbizDocumentNumber: string;
  llcName: string;
  alternateNames: string[];
  status: string;
  contactName: string;
  contactEmail: string;
  createdAt: string;
  filedAt: string | null;
  formedAt: string | null;
  rejectedAt: string | null;
  groups: FilingGroup[];
  seriesFiledAt: string | null;
  copiedFields: Record<string, boolean>;
  series: { name: string; covered: boolean }[];
  documents: { id: string; kind: string; title: string; createdAt: string; source: "card" | "portal" }[];
  hasArticles: boolean;
  /** The client appointed us to sign the Articles: the Statement of
   *  Authorized Representative is made when the Articles go up, and the
   *  upload needs the Florida document number to name the company. */
  articlesSignedByUs: boolean;
  certStatusPurchased: boolean;
  certifiedCopyPurchased: boolean;
  hasCertStatus: boolean;
  hasCertifiedCopy: boolean;
  /** The company's Florida document number, once the office typed it. */
  documentNumber: string;
  /** The order took our registered agent service. */
  raService: boolean;
  raRenewalDate: string | null;
}

